from pathlib import Path
import json
D=Path(__file__).resolve().parent
def get(n):return json.loads((D/n).read_bytes())
def f(x):return f'{x:.2f}'.replace('.',',')
def effect(c,k):return f(c['micro'][k]*100)+' п.п. ['+f(c['ci'][0][k]*100)+'; '+f(c['ci'][1][k]*100)+']'
def main():
    r=get('results.json')['panels'];v=r['dev'];p=v['contrasts']['full_mask minus document_mask'];op=r['outside'];qc=v['contrasts']['match_mask minus document_mask']
    m=get('model-audit.json')['ungraded_probability_similarities']['dev'];full='Преимущество полной модели над структурной подтвердилось.' if p['ci'][0][1]>0 else 'Преимущество полной модели над структурной по заранее выбранному критерию не подтвердилось.'
    table=['| Поправка к Qwen | 101, MSS@5/8 | 101, MSS@5/8 с отсрочкой | 204, MSS@5/8 | 204, MSS@5/8 с отсрочкой |','|---|---|---|---|---|']
    for name,label in [('qwen','Исходная семантическая выдача'),('document','Только свойства фрагмента, 20 признаков'),('match','Взаимодействие запроса и фрагмента, 77 признаков'),('full','Полная обученная модель, 109 признаков')]:
        cells=[]
        for panel in [v,op]:
            for suffix in ('','_mask'):
                z=panel['arms'][name+suffix]['totals'];cells.append(f'{int(z[0])} / {int(z[1])}')
        table.append('| '+label+' | '+' | '.join(cells)+' |')
    ar=v['arms'];full8=int(ar['full_mask']['totals'][1]);doc8=int(ar['document_mask']['totals'][1]);match8=int(ar['match_mask']['totals'][1]);base8=int(ar['qwen_mask']['totals'][1])
    txt=[f"**{full}** На 101 состоянии из 34 репозиториев с одинаковой отсрочкой просмотренного полная модель собрала полный набор среди первых восьми в **{full8}** случаях, только свойства фрагмента — в **{doc8}**. Основная разница **{effect(p,1)}**, выигрышей {p['wins'][1]}, потерь {p['loss'][1]}, изменился состав выдачи в {p['set8']} состояниях. Исходный Qwen дал {base8}, модель совпадения с запросом — {match8}. [План до получения новых Qwen-выдач](PROTOCOL_RU.md) · [Проверка самого эффекта](../facet_confirmation/REPORT_RU.md)",
     '\n'.join(table),
     f"Дополнительная разность признаков совпадения против свойств фрагмента на 101 состоянии составляет {effect(qc,1)}. После удаления свойств самого фрагмента разность полной модели и модели совпадения составляет {effect(v['contrasts']['full_mask minus match_mask'],1)}. На исходной панели из 204 состояний основная разность между полной и структурной версиями составляла {effect(op['contrasts']['full_mask minus document_mask'],1)}. Для дополнительных показателей интервалы номинальные, без поправки на множественные сравнения. [Все парные контрасты](results.json)",
     f"Роли двух наборов признаков различаются уже на уровне оценок. До открытия результатов на новых репозиториях медианная по запросам корреляция Спирмена полной вероятности с моделью совпадений равнялась {f(m['full vs match']['median_spearman'])}, а с признаками самого фрагмента — {f(m['full vs document']['median_spearman'])}. У двух частичных моделей в среднем общими оказались {f(m['match vs document']['mean_top8_overlap'])} из восьми первых кандидатов до добавления семантического ранга. Среди крупных стандартизованных коэффициентов структурной модели — индикаторы документации, тестового пути и количество строк. Эти коэффициенты измеряют ассоциацию с калибровочной разметкой при коррелированных признаках. Они не устанавливают причинную важность синтаксического свойства для решения агента. [Все коэффициенты и сравнения вероятностей](model-audit.json)",
     "Общее число кандидатов и стоимость всегда сравниваются в одной группе запросов. Переподготовка полной модели воспроизвела ранее зафиксированные вероятности с максимальным расхождением менее 10⁻¹⁵. Для двух абляций менялся разрешённый набор признаков; и единая обучающая цель, и 179 состояний для обучения, и ранги исходной Qwen общие. Запросная абляция включает признаки запроса во взаимодействии с типом теста и числом объявлений. Она сохраняет косвенное влияние свойств самого документа. Двенадцать чисто запросных признаков присутствуют только в полной модели, поэтому отдельный вклад их группы из данного опыта не следует. [Веса и схема](models.json) · [Воспроизведение](REPRODUCE_RU.md)",
     "Обе панели входят в публичный калибровочный набор SERBench. Подтверждающий срез расположен в других репозиториях и до фиксации протокола ещё не имел результатов для новой комбинации с Qwen. Результаты прежних методов на этих репозиториях использовались в других работах проекта. [История использования панели](../facet_confirmation/SPLITS_RU.md)"]
    cost=get('cost-audit.json')
    txt.insert(-1,f"При числовом входе из того же токенизатора построение всех 109 признаков заняло {f(cost['derived_token_field_seconds'])} с на {cost['states']} состоянии, {cost['candidates']} кандидатах и {cost['distinct_excerpts']} разных выдержках; среднее {f(cost['field_ms_per_state'])} мс на запрос. Само применение логистической регрессии к уже готовым векторам потребовало в среднем {f(cost['inference']['full']['median_ms_per_state']*1000)} мкс на запрос, взята медиана семи полных повторений. Замер на одном CPU-потоке, с локальным кешем разбора повторяющихся источников. Чтение архивов, первичная токенизация, плотный поиск и построение окончательного порядка исключены. [Измерения стоимости](cost-audit.json)")
    (D/'REPORT_RU.md').write_text('# Что даёт обученной оценке фрагмента её преимущество\n\n'+'\n\n'.join(txt)+'\n',encoding='utf8')
if __name__=='__main__':main()

